"use strict";

const table = require("./lib/table");
const { asPromise, asSync } = require("./lib/wrap");

// Each entry point answers with the function that gives the name back,
// wrapped the same way as the call that took it.
async function hold(name, options) {
  const giveBack = await asPromise(table.take)(name, options);
  return asPromise(giveBack);
}

function holdSync(name, options) {
  return asSync(asSync(table.take)(name, options));
}

function checkSync(name) {
  return asSync(table.isTaken)(name);
}

module.exports = hold;
module.exports.hold = hold;
module.exports.holdSync = holdSync;
module.exports.checkSync = checkSync;
